from langchain_ollama import OllamaLLM, OllamaEmbeddings
from chromadb import PersistentClient
import uuid
import re
import numpy as np
from numpy.linalg import norm
from numpy import dot

# Load Ollama models
ollama_model = OllamaLLM(
    base_url='http://localhost:11434', 
    model='deepseek-r1:8b',
    temperature=0.3
)
ollama_embedding = OllamaEmbeddings(
    base_url='http://localhost:11434', 
    model='nomic-embed-text'
)

# Function to chunk large text into smaller segments
def chunk_text(text, max_words=150):
    """
    Splits the text into smaller chunks of approximately max_words.
    """
    words = text.split()
    chunks = [" ".join(words[i:i+max_words]) for i in range(0, len(words), max_words)]
    return chunks

# Function to remove <think> tags from DeepSeek output
def remove_think_tags(text):
    clean_text = re.sub(r'<think>.*?</think>', '', text, flags=re.DOTALL)
    return clean_text.strip()

# Function to cluster the meeting transcript
def cluster_meeting_transcript(meeting_transcript):
    # Split the transcript into sentence-like chunks
    sentences = re.split(r'(?<=[.!?]) +', meeting_transcript)
    
    # Create overlapping chunks for better context preservation
    chunk_size = 5  # Sentences per chunk
    step_size = 2    # Sentences to move forward
    chunks = []
    for i in range(0, len(sentences), step_size):
        chunk = ' '.join(sentences[i:i+chunk_size])
        chunks.append(chunk)
    
    # Generate embeddings for each chunk
    embeddings = ollama_embedding.embed_documents(chunks)
    
    # Calculate cosine similarities between consecutive chunks
    similarities = []
    for i in range(len(embeddings)-1):
        emb1 = embeddings[i]
        emb2 = embeddings[i+1]
        cos_sim = dot(emb1, emb2) / (norm(emb1) * norm(emb2))
        similarities.append(cos_sim)
    
    # Smooth similarities using moving average
    window_size = 3
    smoothed_sims = []
    for i in range(len(similarities)):
        start = max(0, i - window_size//2)
        end = min(len(similarities), i + window_size//2 + 1)
        window = similarities[start:end]
        smoothed_sims.append(np.mean(window))
    
    # Dynamic threshold calculation
    avg_sim = np.mean(smoothed_sims)
    std_sim = np.std(smoothed_sims)
    threshold = avg_sim - 1.2 * std_sim
    
    # Find topic boundaries
    boundaries = [0]
    for i, sim in enumerate(smoothed_sims):
        if sim < threshold:
            boundaries.append(i+1)
    
    # Create clusters
    clusters = []
    for i in range(1, len(boundaries)):
        start = boundaries[i-1]
        end = boundaries[i]
        cluster = ' '.join(chunks[start:end])
        clusters.append(cluster)
    
    # Add remaining chunks after last boundary
    if boundaries[-1] < len(chunks):
        cluster = ' '.join(chunks[boundaries[-1]:])
        clusters.append(cluster)
    
    return clusters


# Process the meeting transcript and generate clusters
clustered_paragraphs = cluster_meeting_transcript(meeting_transcript)

# Generate detailed summaries for each cluster
summary_clustered = []

for cluster in clustered_paragraphs:
    # If the cluster is too large, split it into smaller chunks
    if len(cluster.split()) > 300:  # Handling large clusters
        chunks = chunk_text(cluster, max_words=150)
        
        # Generate a summary for each chunk
        chunk_summaries = []
        for chunk in chunks:
            prompt = (
                "Please provide a precise and detailed summary of the following meeting transcript segment. "
                "Explain deeply what is being discussed, covering all the important topics and insights:\n\n"
                f"{chunk}"
            )
            chunk_summary = ollama_model(prompt)
            clean_summary = remove_think_tags(chunk_summary)
            chunk_summaries.append(clean_summary)
        
        # Combine the chunk summaries into a final summary
        final_summary = " ".join(chunk_summaries)
        summary_clustered.append(final_summary)
    else:
        # If the cluster is small, summarize it directly
        prompt = (
            "Please provide a precise and detailed summary of the following meeting transcript segment. "
            "Explain deeply what is being discussed, covering all the important topics and insights:\n\n"
            f"{cluster}"
        )
        summary = ollama_model(prompt)
        clean_summary = remove_think_tags(summary)
        summary_clustered.append(clean_summary)
        # Combine all individual summaries into one final text
        combined_text = " ".join(summary_clustered)

# Generate the final high-level summary based on the combined summaries
        final_prompt = (
    "Please provide a high-level detailed summary for the following collection of meeting summaries. "
    "Extract the most important topics, key insights, and discussion points without redundancy:\n\n"
    f"{combined_text}"
    )
final_summary = ollama_model.invoke(final_prompt)
clean_final_summary = remove_think_tags(final_summary)

# Generate LaTeX Minutes of Meeting (MoM) from the final summary
latex_prompt = f"""
You are a professional technical writer skilled in creating corporate documentation in LaTeX format.

I have a clean and detailed meeting summary from a corporate meeting, and I need you to generate a professional-looking "Minutes of Meeting (MoM)" in LaTeX format based on the summary.

### Requirements:
1. The document should have a **title**: "Minutes of Meeting".

2. Include the following sections:
   - **Agenda** (Extract the main discussion topics from the summary)
   - **Discussion Points** (Detail the major discussion points from the summary)
   - **Action Items** (If any action items are mentioned, generate a professional "Action Items" list)
3. The formatting should be clean, professional, and suitable for a corporate environment.
4. Ensure the LaTeX code is clean and can be directly compiled into PDF.

Here is the meeting summary text:
{clean_final_summary}

Now, based on the meeting summary, please generate a clean, professional, and structured LaTeX code for the Minutes of Meeting.
"""

latex_code = ollama_model.invoke(latex_prompt)
print(latex_code)



